SELECT b.id bid,b.name,d.id target_id,v.f field_name,CASE v.type WHEN 'numeric' THEN CASE WHEN v.roundval THEN to_jsonb(round(m.number_value)) ELSE to_jsonb(m.number_value) END WHEN 'integer' THEN to_jsonb(round(m.number_value)::int) WHEN 'boolean' THEN to_jsonb(true) ELSE to_jsonb(trim(regexp_replace(m1.val,'[[:space:]]+',' ','g'))) END new_value,v.type value_type,'project_material_library' source_table,l.id source_id,'page:'||v.pg source_field,'internal_archived_page' source_kind,v.unit,v.note||'; page_sha256='||v.hash note
FROM specs v JOIN public.project_material_library l ON l.id=v.lib JOIN public.project_material_library_pages p ON p.extraction_id=l.id AND p.page_number=v.pg AND p.content_sha256=v.hash JOIN public.buildings b ON b.id=v.bid JOIN public.building_brochure_data d ON d.building_id=b.id CROSS JOIN LATERAL (SELECT (regexp_match(p.content->>'native_text',v.pat))[1] val,CASE WHEN v.addpat IS NOT NULL THEN (regexp_match(p.content->>'native_text',v.addpat))[1] ELSE NULL END aval) m1 CROSS JOIN LATERAL (SELECT CASE WHEN v.type IN ('numeric','integer') THEN CASE WHEN v.f='parking_underground_floor' THEN replace(m1.aval,',','')::numeric-replace(m1.val,',','')::numeric+1 ELSE (replace(m1.val,',','')::numeric+coalesce(replace(m1.aval,',','')::numeric,0))*v.mult END END number_value) m
WHERE l.review_state='reviewed' AND EXISTS(SELECT 1 FROM jsonb_array_elements(l.payload->'sections') s WHERE s->>'association_status'='confirmed' AND s->'candidate_building_ids' ? b.id::text AND jsonb_array_length(s->'candidate_building_ids')=1) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(l.payload->'sections') s WHERE s->>'association_status'='confirmed' AND NOT (s->'candidate_building_ids' ? b.id::text))
AND b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.merged_into_id IS NULL AND (b.project_type='stock' OR (b.project_type='future' AND b.is_entered_market=false)) AND (SELECT count(*) FROM public.building_brochure_data y WHERE y.building_id=b.id)=1 AND m1.val IS NOT NULL AND (v.addpat IS NULL OR m1.aval IS NOT NULL)
) SELECT c.* FROM c) i
UNION ALL
