"1669ffe8-f07c-44da-882b-b359b18fa155","f":"developer","type":"text","value":"北京华建房地产有限公司","unit":"company","sources":[{"url":"https://k.sina.com.cn/article_2664057621_9eca4b15020010mc2.html","name":"房天下2023年8月报告（新浪转载）","tier":"secondary"},{"url":"https://www.bj5a-office.com/shangquan/61/127.html","name":"北京写字楼租赁网","tier":"secondary"}],"note":"东环广场东中街9/19号同一项目；两渠道分别列北京华建房地产有限公司、华建房地产有限公司；不混入办公与综合体面积"}]$ext$::jsonb) v(id uuid,f text,type text,value jsonb,unit text,sources jsonb,note text) JOIN public.building_brochure_data d ON d.id=v.id
), a AS (
 SELECT a.*,a.details->>'field_name' f,(a.details->>'building_id')::uuid bid,(a.details->>'evidence_group_id')::uuid eg FROM public.audit_logs a WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v6_100'
), checked AS (
 SELECT a.id,a.f,a.bid,a.target_id,a.eg,a.details,e.target_id expected_id,
 COALESCE(a.target_table='building_brochure_data' AND d.building_id=a.bid AND a.old_values->a.f='null'::jsonb AND a.new_values->a.f IS NOT NULL AND a.new_values->a.f<>'null'::jsonb AND to_jsonb(d)->a.f=a.new_values->a.f AND e.new_value=a.new_values->a.f AND e.source_kind=a.details->>'source_kind' AND e.unit=a.details->>'unit' AND e.sub_batch=(a.details->>'sub_batch')::int AND a.actor_kind='tool' AND a.user_id='codex' AND a.details->>'ai_assisted'='true'
 AND CASE WHEN e.source_kind='external_cross_verified' THEN e.sources=a.details->'source_urls' AND a.details->>'verification_status'='cross_verified' ELSE e.source_id=a.details->>'source_record_id' AND e.source_field=a.details->>'source_field' AND a.details->>'verification_status'='legacy_backfill' END,false) field_ok,
 (SELECT count(*) FROM public.building_data_field_provenance p WHERE p.evidence_group_id=a.eg AND p.is_current AND p.building_id=a.bid AND p.brochure_data_id=d.id AND p.target_table=a.target_table AND p.field_name=a.f AND p.field_value=a.new_values->a.f AND p.source_retrieved_at IS NOT NULL AND p.value_recorded_at IS NOT NULL AND p.evidence_note LIKE 'batch_ref=ai_building_field_backfill_20261125_v6_100;%' AND CASE WHEN e.source_kind='external_cross_verified' THEN p.source_type='internet' AND p.verification_status='cross_verified' AND EXISTS(SELECT 1 FROM jsonb_array_elements(e.sources) s WHERE s->>'url'=p.source_url) ELSE p.source_type IN ('other','brochure') AND p.verification_status='legacy_backfill' END) matched,
 (SELECT count(*) FROM public.building_data_field_provenance p WHERE p.building_id=a.bid AND p.target_table=a.target_table AND p.field_name=a.f AND p.is_current) actual_sources,
 CASE WHEN e.source_kind='external_cross_verified' THEN jsonb_array_length(e.sources) ELSE 1 END expected_sources,
 (SELECT count(distinct p.source_url) FROM public.building_data_field_provenance p WHERE p.evidence_group_id=a.eg AND p.is_current) distinct_urls
 FROM a LEFT JOIN public.building_brochure_data d ON d.id=a.target_id::uuid LEFT JOIN expected e ON e.target_id=d.id AND e.field_name=a.f AND e.bid=a.bid
)
SELECT (SELECT count(*) FROM a) audit_count,(SELECT count(*) FROM expected) manifest_fields,
 count(distinct (target_id,f)) unique_fields,count(distinct bid) buildings,count(distinct f) field_types,
 count(*) FILTER(WHERE field_ok AND matched=expected_sources AND actual_sources=expected_sources AND (details->>'source_kind'<>'external_cross_verified' OR distinct_urls=expected_sources)) verified,
 sum(matched) matching_provenance,
 (SELECT count(*) FROM public.building_data_field_provenance WHERE is_current AND evidence_note LIKE 'batch_ref=ai_building_field_backfill_20261125_v6_100;%') persisted_sources,
 (SELECT count(*) FROM public.audit_logs WHERE action_type='AI_FIELD_ROLLBACK' AND details->>'rollback_batch_ref'='ai_building_field_backfill_20261125_v6_100_rollback') persisted_rollbacks,
 (SELECT count(*) FROM a JOIN public.audit_logs h ON h.target_table=a.target_table AND h.target_id=a.target_id AND h.action_type='AI_FIELD_FILL' AND h.id<a.id AND h.details->>'batch_ref' IS DISTINCT FROM 'ai_building_field_backfill_20261125_v6_100' AND (h.details->>'field_name'=a.f OR h.new_values ? a.f)) prior_duplicates,
 coalesce(jsonb_agg(jsonb_build_object('target',target_id,'field',f,'field_ok',field_ok,'matched',matched,'expected',expected_sources)) FILTER(WHERE NOT field_ok OR matched<>expected_sources OR actual_sources<>expected_sources OR (details->>'source_kind'='external_cross_verified' AND distinct_urls<>expected_sources)),'[]'::jsonb) failures
FROM checked;